def a(url,label,cls=''):
 external=url.startswith('http');return f'<a href="{E(url,quote=True)}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+(f' class="{cls}"' if cls else '')+'>'+label+(' <span aria-hidden="true">↗</span>' if external else '')+'</a>'
def dotted(left,right,n=43):return left+'.'*max(2,n-len(left)-len(right))+right
# Only text content, accessibility metadata, and link wrappers change on the home panel.
changes={}
def change(x,y,label,href=None,aria=None):changes[(str(x),str(y))]=(label,href,aria)
