# Numeric y attributes generated by Python can contain floating-point tails.
def lookup(x,y):
 for (cx,cy),value in changes.items():
  if x==cx and abs(float(y)-float(cy))<.001:return value
 return None
def replace_text(match):
 attrs,old=match.group(1),match.group(2);x=re.search(r'\bx="([^"]+)"',attrs);y=re.search(r'\by="([^"]+)"',attrs)
 if not x or not y:return match.group(0)
 val=lookup(x.group(1),y.group(1))
 if not val:return match.group(0)
 label,href,aria=val
 result=f'<text{attrs}>{E(label)}</text>'
 if href:
  # Generous row targets; keep all source strokes/paths untouched.
  px=float(x.group(1));py=float(y.group(1));width=112 if px==232 else (127 if 449<=py<530 else 209)
  target=f'<rect class="hit-area" x="{px-2}" y="{py-8.8}" width="{width+4}" height="10.2" fill="transparent"/>'
  result=f'<a class="panel-link" href="{href}" aria-label="{E(aria or label.replace("."," "),quote=True)}">{target}{result}</a>'
 return result
panel=re.sub(r'<text([^>]*)>(.*?)</text>',replace_text,source,flags=re.S)
panel=panel.replace('role="img"','role="group"').replace('<title id="title">CMX-7500 GEN 2A RADCOMMS IMGU</title>','<title id="title">natochi — personal terminal</title>').replace(re.search(r'<desc.*?</desc>',panel,re.S).group(0),'<desc id="description">Nacho Bernardo, Santiago de Chile. Explore my profile, projects, writing, reading and contact channels.</desc>')
# The final scanline layer is decorative and must not intercept links.
panel=panel.replace('fill="url(#scan)"','fill="url(#scan)" pointer-events="none"')
