(ROOT/'index.html').write_text(head+'<title>natochi — personal terminal</title><meta name="description" content="Nacho Bernardo. Building businesses, communities and cool things from Santiago de Chile."><style>'+home_css+'</style></head><body><a class="skip" href="/24/about/">Read my profile</a><main><!--email_off-->'+panel+'<!--/email_off--></main></body></html>')
# Reuse original instruments without redrawing their internal details.
def asset(name,viewbox,fragment):
 svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+viewbox+'"><style>text{font-family:Menlo,Consolas,monospace;font-weight:400;letter-spacing:.05px;white-space:pre}</style>'+re.search(r'<defs>.*?</defs>',source,re.S).group(0)+fragment+'</svg>'
 (ROOT/'assets'/name).write_text(svg)
asset('radar.svg','228 128 120 96',source[source.index('<circle cx="243"'):source.index('<text x="232" y="238"')])
asset('spectrum.svg','5 340 343 96',source[source.index('<g shape-rendering="crispEdges">'):source.index('<text x="8" y="452.0"')])
asset('identity.svg','164 4 53 25',source[source.index('<rect x="165"'):source.index('<text x="8" y="35"')])
